const app=document.getElementById('app');
function today(){return new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Shanghai',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());}
let lastDay=today();
function math(tex,extra=''){const el=document.createElement('div');el.className='formula '+extra;katex.render(tex,el,{displayMode:true,throwOnError:true,output:'htmlAndMathml',strict:'error'});return el;}
function fit(){document.querySelectorAll('.formula').forEach(el=>{el.style.fontSize='';const target=el.querySelector('.katex');if(!target)return;const desired=parseFloat(getComputedStyle(el).fontSize);const width=target.getBoundingClientRect().width;const available=el.clientWidth-4;if(width>available)el.style.fontSize=Math.max(14,desired*available/width)+'px';});}
function render(){const params=new URLSearchParams(location.search);const isAnswer=params.get('answer')==='limit'||params.get('answer')==='integral';const raw=params.get('date');const date=isAnswer&&/^\d{4}-\d{2}-\d{2}$/.test(raw||'')&&!isNaN(Date.parse(raw+'T00:00:00+08:00'))?raw:today();const [limit,integral]=getProblems(date);const display=date.replaceAll('-',' / ');app.innerHTML=`<header><span class="date">${display}</span><span class="mark"><span class="dot"></span>每日一极 · 每日一积</span></header>`;
if(!isAnswer){app.insertAdjacentHTML('beforeend','<div class="hero"><h1>Everyday Calculas Exercise</h1><p class="hero-sub">每日两题，留一点时间给思考。</p></div>');[limit,integral].forEach((p,i)=>{const section=document.createElement('section');section.className='problem';section.innerHTML=`<div class="label"><span class="number">0${i+1}</span><span class="cn">${i?'每日一积':'每日一极'}</span><span>/ ${i?'INTEGRAL':'LIMIT'}</span></div>`;const link=document.createElement('a');link.className='formula-link';link.href=`?answer=${i?'integral':'limit'}&date=${date}`;link.setAttribute('aria-label',`查看${i?'积分':'极限'}的分步答案`);link.append(math(p.q));link.insertAdjacentHTML('beforeend','<span class="arrow" aria-hidden="true">↗</span>');section.append(link);if(i===1)section.insertAdjacentHTML('beforeend','<p class="hint">点击公式，查看答案 ↗</p>');app.append(section);});app.insertAdjacentHTML('beforeend','<footer class="footer"><span>先独立想一想，再看下一步。</span><em>A little calculus, every day.</em></footer>');}
else{const integralAnswer=params.get('answer')==='integral';const p=integralAnswer?integral:limit;app.className='answer';app.insertAdjacentHTML('beforeend',`<div class="solution-head"><div class="label"><span class="number">0${integralAnswer?2:1}</span><span class="cn">${integralAnswer?'每日一积':'每日一极'}</span></div><h1 class="solution-title">一步一步，抵达答案。</h1></div>`);const question=document.createElement('div');question.className='question-box';question.append(math(p.q));app.append(question);const steps=document.createElement('div');steps.className='steps';p.s.forEach((s,i)=>{const row=document.createElement('div');row.className='step';row.innerHTML=`<span class="step-num">${String(i+1).padStart(2,'0')}</span>`;row.append(math(s));steps.append(row);});app.append(steps);const footer=document.createElement('footer');footer.className='footer';const back=document.createElement('a');back.className='back';back.href='/';back.textContent='← 返回今日题目';const tip=document.createElement('span');tip.textContent=p.tip;footer.append(back,tip);app.append(footer);}
if(!isAnswer)app.className='';document.title=isAnswer?'分步答案 · 每日一极，每日一积':'每日一极，每日一积';requestAnimationFrame(fit);}
document.fonts.ready.then(fit);window.addEventListener('resize',fit);window.addEventListener('pageshow',()=>{if(today()!==lastDay){lastDay=today();render();}});document.addEventListener('visibilitychange',()=>{if(!document.hidden&&today()!==lastDay){lastDay=today();render();}});setInterval(()=>{if(today()!==lastDay){lastDay=today();if(!new URLSearchParams(location.search).has('answer'))render();}},1000);render();
